from decrypt import decrypt_flag

p, g, A = {"p": "", "g": "0x02", "A": ""}.values()
B = {"B": ""}['B']
iv, ciphertext = {"iv": "8b0cdbef1e79574427e3fac85e5886fc", "encrypted": "c6d4e0268839feee86ef0fb4d3efd8fa5f6635d95c2923421412fb0e4c00f4e558a7dbc5d69d50ccad18b8c068513971"}.values()
inv_g = pow(int(g, 16), -1, int(p, 16))
a = int(A, 16) * inv_g % int(p, 16)
S = int(B, 16) * a % int(p, 16)
flag = decrypt_flag(S, iv, ciphertext)
print(flag)
